@Component("promotion-handler")
@ProcessingGroup("promotion-processing-group")
public class PromotionEventHandler {
	
	// core constructor
	PromotionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePromotionEvent
     */
    @EventHandler
    public void handle( CreatePromotionEvent event) {
        entityManager.persist(new Promotion(event.getPromotionId(), event.getName(), event.getCode(), event.getValue(), event.getStartDate(), event.getEndDate(), event.getAsStackable(), event.getMaxRedemptions(), event.getMerchant(), event.getChannels(), event.getApplicableProducts(), event.getApplicableCategories(), event.getCoupons(), event.getPromotionType(), event.getDiscountType()));
    }

    /*
     * @param	event UpdatePromotionEvent
     */
    @EventHandler
    public Promotion handle( UpdatePromotionEvent event) {
    	entityManager.merge(new Promotion(event.getPromotionId(), event.getName(), event.getCode(), event.getValue(), event.getStartDate(), event.getEndDate(), event.getAsStackable(), event.getMaxRedemptions(), event.getMerchant(), event.getChannels(), event.getApplicableProducts(), event.getApplicableCategories(), event.getCoupons(), event.getPromotionType(), event.getDiscountType()));
    }
    
    /*
     * @param	event DeletePromotionEvent
     */
    @EventHandler
    public void on( DeletePromotionEvent event) {
    	Promotion entity = new Promotion();
   
    	// ------------------------------------------
    	// apply the PromotionId
    	// ------------------------------------------
    	entity.setPromotionId( event.getPromotionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PromotionRepository promotionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PromotionEventHandler.class.getName());

}
